"""Re-execute every listing and diff it against the output printed in the book.

This is the mechanism that keeps *Python Zero to Godhood* honest. Every
"Verified output" block in the prose is generated by, and checked against, a
file under `chNN/expected/<major.minor>/`. When CPython changes an opcode name
or a repr, `make verify` fails and names the listing. Version drift becomes a
failing test instead of a reader's bug report.

Usage
-----
    python3 -m _harness.verify              # check every listing for this interpreter
    python3 -m _harness.verify --record     # (re)generate expected output
    python3 -m _harness.verify ch18         # restrict to one chapter

Version gating
--------------
A listing that only applies to some interpreters declares it on line 1 or 2:

    # requires: 3.14+

Gated listings are skipped, and reported as skipped, on other versions.

Normalisation
-------------
Memory addresses, temp paths, and `object at 0x...` reprs are scrubbed before
comparison; they vary per run and carry no pedagogical content.
"""

from __future__ import annotations

import argparse
import difflib
import re
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
VER = f"{sys.version_info.major}.{sys.version_info.minor}"

# Only scrub hex that is genuinely a memory address. An earlier version matched
# any long hex literal, which silently destroyed real data: the immortality
# sentinel in ch019 (0xffffffff on 3.13, 0xc0000000 on 3.14) was rewritten to
# 0xADDR, erasing the exact version difference the listing exists to show.
# Addresses in CPython reprs always follow "at ".
#
# The {6,} bound is load-bearing for IDEMPOTENCY, not just precision. Scrubbing
# runs on both the live output and the stored expected file, so it must be safe
# to apply twice. With `+` instead of `{6,}` the placeholder 0xADDR re-matched
# its own 'ADD' (all valid hex) and became 0xADDRR on the second pass, failing
# every listing that prints a code object. 0xADDR has only 3 hex digits, so the
# 6-digit floor makes the substitution a fixed point.
_SCRUB = [
    (re.compile(r"(?<=at )0x[0-9a-fA-F]{6,}"), "0xADDR"),
    (re.compile(r"(file \")[^\"]*(\")"), r"\1<path>\2"),
    (re.compile(r"\s+$", re.MULTILINE), ""),
]


def scrub(text: str) -> str:
    for pat, rep in _SCRUB:
        text = pat.sub(rep, text)
    return text.strip() + "\n"


def requirement(path: Path) -> tuple[int, int] | None:
    """Parse a `# requires: 3.14+` marker from the head of a listing."""
    with path.open(encoding="utf-8") as fh:
        for _ in range(3):
            line = fh.readline()
            if not line:
                break
            m = re.match(r"#\s*requires:\s*(\d+)\.(\d+)\+", line)
            if m:
                return int(m.group(1)), int(m.group(2))
    return None


def listings(chapters: list[str]) -> list[Path]:
    found: list[Path] = []
    for ch in sorted(chapters):
        found += sorted((ROOT / ch).glob("l[0-9][0-9]_*.py"))
    return found


def run(path: Path) -> tuple[int, str]:
    proc = subprocess.run(
        [sys.executable, path.name],
        cwd=path.parent, capture_output=True, text=True, timeout=120,
    )
    return proc.returncode, proc.stdout + proc.stderr


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("chapters", nargs="*", help="e.g. ch18; default: all")
    ap.add_argument("--record", action="store_true", help="write expected output")
    args = ap.parse_args()

    chapters = args.chapters or sorted(
        p.name for p in ROOT.iterdir() if re.fullmatch(r"ch\d+", p.name)
    )
    if not chapters:
        print("no chapters found", file=sys.stderr)
        return 1

    ok = failed = skipped = 0
    for path in listings(chapters):
        rel = f"{path.parent.name}/{path.name}"
        req = requirement(path)
        if req and sys.version_info[:2] < req:
            print(f"SKIP  {rel}  (requires {req[0]}.{req[1]}+, running {VER})")
            skipped += 1
            continue

        code, out = run(path)
        out = scrub(out)
        if code != 0:
            print(f"ERROR {rel}  (exit {code})")
            print("".join(f"      | {ln}\n" for ln in out.splitlines()[:15]))
            failed += 1
            continue

        exp_path = path.parent / "expected" / VER / f"{path.stem}.out"
        if args.record:
            exp_path.parent.mkdir(parents=True, exist_ok=True)
            exp_path.write_text(out, encoding="utf-8")
            print(f"REC   {rel}  -> {exp_path.relative_to(ROOT)}")
            ok += 1
            continue

        if not exp_path.exists():
            print(f"MISS  {rel}  (no expected output for {VER}; run --record)")
            failed += 1
            continue

        want = scrub(exp_path.read_text(encoding="utf-8"))
        if want == out:
            print(f"ok    {rel}")
            ok += 1
        else:
            print(f"FAIL  {rel}  (output drifted on CPython {VER})")
            diff = difflib.unified_diff(
                want.splitlines(), out.splitlines(),
                fromfile="expected", tofile="actual", lineterm="", n=1,
            )
            for line in list(diff)[:24]:
                print(f"      {line}")
            failed += 1

    print(f"\n{ok} ok, {failed} failed, {skipped} skipped  (CPython {VER})")
    return 1 if failed else 0


if __name__ == "__main__":
    raise SystemExit(main())
